<?php
declare(strict_types=1);
function wb_events_schema(PDO $db):void {$db->exec('CREATE TABLE IF NOT EXISTS workbook_cell_events(id INTEGER PRIMARY KEY AUTOINCREMENT,sheet_id TEXT NOT NULL,sheet_name TEXT NOT NULL,row_index INTEGER NOT NULL,col_index INTEGER NOT NULL,address TEXT NOT NULL,actor TEXT NOT NULL,version INTEGER NOT NULL,before_cell TEXT NOT NULL,after_cell TEXT NOT NULL,created_at TEXT NOT NULL);CREATE INDEX IF NOT EXISTS workbook_cell_lookup ON workbook_cell_events(sheet_id,row_index,col_index,id);CREATE TABLE IF NOT EXISTS workbook_input_issues(id INTEGER PRIMARY KEY AUTOINCREMENT,sheet_id TEXT NOT NULL,sheet_name TEXT NOT NULL,address TEXT NOT NULL,actor TEXT NOT NULL,version INTEGER NOT NULL,value TEXT NOT NULL,errors TEXT NOT NULL,created_at TEXT NOT NULL);CREATE INDEX IF NOT EXISTS workbook_issue_actor ON workbook_input_issues(created_at,actor);CREATE TABLE IF NOT EXISTS workbook_product_checks(id INTEGER PRIMARY KEY AUTOINCREMENT,actor TEXT NOT NULL,valid INTEGER NOT NULL,created_at TEXT NOT NULL);CREATE INDEX IF NOT EXISTS workbook_check_actor ON workbook_product_checks(created_at,actor)');}
function wb_events_record(PDO $db,array $changes,array $snapshot,string $actor,int $version,string $now):void {
 wb_events_schema($db);$byName=[];foreach($snapshot['sheets'] as $sid=>$s)$byName[$s['name']]=$sid;$save=$db->prepare('INSERT INTO workbook_cell_events(sheet_id,sheet_name,row_index,col_index,address,actor,version,before_cell,after_cell,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)');$issue=$db->prepare('INSERT INTO workbook_input_issues(sheet_id,sheet_name,address,actor,version,value,errors,created_at) VALUES(?,?,?,?,?,?,?,?)');$catalog=null;
 foreach($changes as $change)if(($change['field']??'')==='Trang tính'&&empty($change['before'])&&isset($byName[$change['sheet']??''])){$sid=$byName[$change['sheet']];foreach(($snapshot['sheets'][$sid]['cellData']??[]) as $r=>$cells)if((int)$r>0)foreach($cells as $c=>$cell)if((int)$c>1&&(!empty($cell['f'])||trim((string)($cell['v']??''))!=='')){$n=(int)$c+1;$letter='';while($n){$n--;$letter=chr(65+$n%26).$letter;$n=intdiv($n,26);}$changes[]=['sheet'=>$change['sheet'],'cell'=>$letter.((int)$r+1),'before'=>[],'after'=>$cell];}}
 foreach($changes as $change){if(!isset($change['cell'],$change['sheet'])||!preg_match('/^([A-Z]+)(\d+)$/D',$change['cell'],$m))continue;$sid=$byName[$change['sheet']]??null;if($sid===null)continue;$col=0;foreach(str_split($m[1]) as $ch)$col=$col*26+ord($ch)-64;$col--;$row=(int)$m[2]-1;$before=$change['before']??[];$after=$change['after']??[];if($row>0&&!empty($snapshot['sheets'][$sid]['cellData'][$row][0]['custom']['victorTotal']))continue;$save->execute([$sid,$change['sheet'],$row,$col,$change['cell'],$actor,$version,json_encode($before,JSON_UNESCAPED_UNICODE),json_encode($after,JSON_UNESCAPED_UNICODE),$now]);
  $label=mb_strtoupper(trim((string)($snapshot['sheets'][$sid]['cellData'][0][$col]['v']??'')),'UTF-8');$value=trim((string)($after['v']??''));if($row<1||!in_array($label,['SẢN PHẨM / SIZE','SẢN PHẨM'],true)||$value===''||$value===trim((string)($before['v']??''))||!function_exists('board_lines')||!function_exists('board_catalog'))continue;$catalog??=board_catalog($db);$parsed=board_lines($value,$catalog);$info=report_sheet_info($change['sheet']);$errors=array_merge($parsed['errors'],board_gender_errors($parsed,$info['gender']));$db->prepare('INSERT INTO workbook_product_checks(actor,valid,created_at) VALUES(?,?,?)')->execute([$actor,$errors?0:1,$now]);if($errors)$issue->execute([$sid,$change['sheet'],$change['cell'],$actor,$version,$value,json_encode($errors,JSON_UNESCAPED_UNICODE),$now]);
 }
}
function wb_cell_history(PDO $db,array $input):array {
 team_require('history');wb_events_schema($db);$sid=(string)($input['sheet']??'');$row=filter_var($input['row']??null,FILTER_VALIDATE_INT);$col=filter_var($input['col']??null,FILTER_VALIDATE_INT);if(strlen($sid)>200||$row===false||$col===false||$row<0||$col<0||$row>=50000||$col>=512)throw new RuntimeException('Địa chỉ ô không hợp lệ.',400);$current=wb_current($db);$name=$current['snapshot']['sheets'][$sid]['name']??'';if($name==='')throw new RuntimeException('Không tìm thấy sheet.',404);$q=$db->prepare('SELECT actor,version,before_cell,after_cell,created_at,address FROM workbook_cell_events WHERE sheet_id=? AND row_index=? AND col_index=? ORDER BY id DESC LIMIT 100');$q->execute([$sid,$row,$col]);$rows=$q->fetchAll();foreach($rows as &$r){$r['before']=json_decode($r['before_cell'],true);$r['after']=json_decode($r['after_cell'],true);unset($r['before_cell'],$r['after_cell']);}unset($r);
 if(!$rows){$n=$col+1;$letter='';while($n){$n--;$letter=chr(65+$n%26).$letter;$n=intdiv($n,26);}$address=$letter.($row+1);try{$q=$db->prepare("SELECT a.username AS actor,a.created_at,json_extract(a.details,'$.version') AS version,json_extract(j.value,'$.before') AS before_cell,json_extract(j.value,'$.after') AS after_cell FROM (SELECT username,created_at,details FROM people_audit WHERE event IN('workbook_save','board') ORDER BY id DESC LIMIT 300) a,json_each(a.details,'$.changes') j WHERE json_extract(j.value,'$.sheet')=? AND json_extract(j.value,'$.cell')=? ORDER BY a.created_at DESC LIMIT 100");$q->execute([$name,$address]);foreach($q as $r){$r['before']=json_decode($r['before_cell']??'null',true);$r['after']=json_decode($r['after_cell']??'null',true);unset($r['before_cell'],$r['after_cell']);$rows[]=$r;}}catch(PDOException $e){if(!str_contains($e->getMessage(),'no such table'))throw $e;}}
 return ['sheet'=>$name,'rows'=>$rows,'note'=>'Lịch sử tại địa chỉ ô, theo các lần lưu lên máy chủ. Dữ liệu cũ được tìm trong 300 nhật ký lưu gần nhất; đổi tên sheet cũ có thể không đối chiếu được.'];
}
